def transform(grid):
    a=[r[:] for r in grid]; h=len(a); w=len(a[0])
    bg=max(set(x for r in a for x in r), key=lambda x:sum(r.count(x) for r in a))
    counts={x:sum(r.count(x) for r in a) for x in set(x for r in a for x in r)}
    bars=[x for x,n in counts.items() if x!=bg and n>=4]
    singles=[x for x,n in counts.items() if x!=bg and n<4]
    fill=singles[0]
    # Isolated signal cells become color 4, as in the demonstration.
    for i in range(h):
      for j in range(w):
        if a[i][j]==fill:a[i][j]=4
    for x in bars:
      pts=[(i,j) for i in range(h) for j in range(w) if a[i][j]==x]
      rows={i for i,j in pts}; cols={j for i,j in pts}
      if len(rows)==1:
        i=next(iter(rows)); lo=min(j for _,j in pts); hi=max(j for _,j in pts)
        rs=range(1,h) if i==0 else (range(h-1) if i==h-1 else [])
        for r in rs:
          for c in range(lo,hi+1):
            if a[r][c]==bg:a[r][c]=fill
    return a
